const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modules=['Counts','Weighing','Sales','Feed','Preventive Care','Procurement','Health','Others'];const icons=['▥','⚖','▣','♧','♡','♧','♧','✎'];const KEY='mesha-studio-v1';
const defaults={sales:{weight:35,margin:0,rate:450,comparison:'>',version:1},shared:{medicines:['Preventive Care','Procurement'],temperature:['Health','Procurement','Preventive Care'],photo:[...modules],approval:[...modules]},libraryVersion:1,history:[],configs:{},sops:{}};
let state;try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(defaults)}catch{state=structuredClone(defaults)}let current='Sales',tab='Configuration',selected='q1',zoom=1,dirty=false,sim=null;const canEdit=()=>$('#role').value==='CEO / CXO';
function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}function closeModal(){$('#overlay').innerHTML='';sim=null;if(current==='Common'&&tab==='Sharing')render()}function modal(title,body,wide=false){$('#overlay').innerHTML=`<div class="modalbg"><section class="modal ${wide?'wide':''}"><div class="modalhead"><h2>${esc(title)}</h2><button onclick="closeModal()" aria-label="Close dialog">✕</button></div>${body}</section></div>`}
function initialSop(m){let health=['Health','Procurement','Preventive Care'].includes(m);return {title:health?(m==='Procurement'?'Animal arrival inspection':m==='Health'?'Temperature assessment':'Pre-vaccination check'):`${m} daily check`,version:0,published:null,nodes:[{id:'start',type:'start',label:'Operator starts inspection',x:260,y:25,next:'q1'},{id:'q1',type:'question',label:health?'What is the animal’s temperature?':'Is the daily check complete?',answer:health?'Number':'Yes / No',unit:health?'°F':'',min:health?90:0,max:health?115:100,x:260,y:155,next:'condition'},{id:'condition',type:'condition',label:health?'Temperature is above threshold':'Check passed?',source:'q1',op:health?'>':'=',value:health?'103':'Yes',yes:'action',no:'end',x:260,y:300},{id:'action',type:'action',label:health?'Request veterinary review':'Request supervisor approval',action:'Request approval',medicine:'',x:70,y:480,next:'end'},{id:'end',type:'end',label:'Complete and record outcome',x:390,y:630}]}}
function sop(){if(!state.sops[current])state.sops[current]=initialSop(current);return state.sops[current]}const fields={Counts:[['Reconciliation tolerance',2,'animals'],['Review overdue after',24,'hours'],['Count frequency',7,'days']],Weighing:[['Target daily gain',180,'g/day'],['Reweigh interval',14,'days'],['Weight reading tolerance',0.2,'kg']],Feed:[['Feed variance alert',5,'%'],['Stock low threshold',7,'days'],['Water check frequency',4,'hours']], 'Preventive Care':[['Drive completion target',95,'%'],['Cold-chain minimum',2,'°C'],['Cold-chain maximum',8,'°C']],Procurement:[['Arrival weight variance',3,'%'],['Inspection due within',24,'hours'],['Approval above',50000,'₹']],Health:[['Review overdue after',2,'hours'],['Follow-up interval',24,'hours'],['Stock low threshold',10,'units']],Others:[['Leave notice period',2,'days'],['Milk preparation tolerance',5,'%'],['Audit retention',365,'days']]};
function go(m,t='Configuration'){current=m;tab=t;selected='q1';render()}function render(){document.body.classList.toggle('editorpage',tab==='Editor');$('#nav').innerHTML=`<div class="section">WORKSPACE</div><button onclick="go('Common','Sharing')" class="${current==='Common'?'active':''}"><span>◇</span>Common workspace</button><div class="section">MODULES</div>${modules.map((m,i)=>`<button class="${current===m?'active':''}" onclick="go('${m}')"><span>${icons[i]}</span>${m}</button>${current===m?`<button class="sub ${tab==='Configuration'?'active':''}" onclick="go('${m}','Configuration')">Business rules</button><button class="sub ${['SOPs','Editor'].includes(tab)?'active':''}" onclick="go('${m}','SOPs')">SOP workflows</button>`:''}`).join('')}<div class="foot">Mesha · goat operating system<br><br>Prototype data stays in this browser.</div>`;if(tab==='Editor'){renderEditor();return}$('#main').innerHTML=`<div class="eyebrow">${current==='Common'?'COMPANY WORKSPACE':esc(current)+' · SETTINGS'}</div><div class="heading"><div><h1>${current==='Common'?'Common configuration & SOPs':esc(current)+' settings'}</h1><p>${current==='Common'?'Define what teams can reuse. Keep ownership with the source module.':'Business rules and operator workflows, managed in one place.'}</p></div><span class="pill">${canEdit()?'CEO / CXO · Can edit':'Read only · '+esc($('#role').value)}</span></div><div class="tabs">${(current==='Common'?['Sharing','Question library','Action library','History']:['Configuration','SOPs','History']).map(t=>`<button class="${tab===t?'active':''}" onclick="go('${current}','${t}')">${t==='Configuration'?'Business rules':t}</button>`).join('')}</div><div id="content"></div>`;if(tab==='History')historyView();else if(current==='Common')commonView();else if(tab==='SOPs')sopsView();else configView()}
function configView(){if(current==='Sales'){$('#content').innerHTML=`<div class="notice">Business rules is a new settings area. The existing Sales Config transaction and master-data screens remain in Sales.</div><div class="two"><div class="card"><div class="cardheader"><div><h2>Sale eligibility & valuation</h2><span class="muted">Owner · Sales / Published v${state.sales.version}</span></div><span class="badge">Shared by default</span></div><label class="field"><span>Eligibility rule</span><div class="inputrow"><select id="comparison" aria-label="Comparison" ${!canEdit()?'disabled':''}><option ${state.sales.comparison==='>'?'selected':''} value=">">Greater than (&gt;)</option><option ${state.sales.comparison==='>='?'selected':''} value=">=">At least (≥)</option></select><input id="weight" aria-label="Minimum sale weight" type="number" min="0.1" step="0.1" value="${state.sales.weight}" ${!canEdit()?'disabled':''}><span style="flex:0;padding:10px">kg</span></div></label><label class="field"><span>Allowed shortfall from minimum</span><div class="inputrow"><input id="margin" aria-label="Allowed shortfall" type="number" min="0" step="0.1" value="${state.sales.margin}" ${!canEdit()?'disabled':''}><span style="flex:0;padding:10px">kg</span></div><div class="hint">Subtract this allowance from the minimum. It is not a ± measurement error.</div></label><div id="formula" class="notice"></div><label class="field"><span>Target selling rate</span><div class="inputrow"><input id="rate" aria-label="Target selling rate" type="number" min="1" value="${state.sales.rate}" ${!canEdit()?'disabled':''}><span style="flex:0;white-space:nowrap;padding:10px">₹ / kg</span></div><div class="hint">Used for indicative farm valuation. Agreed transaction prices are recorded separately.</div></label><div class="actions"><button class="primary" onclick="saveSales()" ${!canEdit()?'disabled':''}>Review & publish rules</button><button onclick="configView()">Revert unsaved edits</button></div></div><div><div class="card"><h2>Where these rules appear</h2><p class="muted">One Sales-owned value. Consumers cannot override it.</p><div class="linkline"><div>Sales · Farm value<br><span class="muted">Eligibility buckets and herd valuation</span></div><span class="badge">Owner</span></div><div class="linkline"><div>Weighing · ADG analytics<br><span class="muted">Sale-ready counts and value projection</span></div><span class="badge blue">Linked</span></div><button style="margin-top:18px" onclick="go('Weighing')">View in Weighing →</button></div><div class="card"><span class="label">Published rule preview</span><div class="stat">₹${state.sales.rate}<small class="muted"> / kg</small></div><div class="muted">Measured weight ${esc(state.sales.comparison)} ${state.sales.weight-state.sales.margin} kg</div><div class="flowmini"><b>Sales</b>→<b>Weighing</b></div><span class="muted">Operators and directors see published values. Only CEO / CXO edits policy.</span></div></div></div>`;['weight','margin','comparison'].forEach(id=>$('#'+id).oninput=formula);formula();return}
let f=fields[current]||[];$('#content').innerHTML=`${current==='Weighing'?`<div class="card"><div class="cardheader"><div><h2>Sales rules used by Weighing</h2><span class="muted">Read only · Live reference to Sales v${state.sales.version}</span></div><span class="badge blue">Required dependency</span></div><div class="grid"><div><span class="label">Sale-ready threshold</span><div class="stat">${esc(state.sales.comparison)} ${state.sales.weight-state.sales.margin}<small class="muted"> kg</small></div></div><div><span class="label">Target selling rate</span><div class="stat">₹${state.sales.rate}<small class="muted"> / kg</small></div></div><div><span class="label">Source of truth</span><button onclick="go('Sales')">Open Sales business rules ↗</button></div></div></div>`:''}<div class="two"><div class="card"><div class="cardheader"><h2>${esc(current)} business rules</h2><span class="badge">Module owned</span></div><div class="notice">Proposed settings for design review. These example values are not connected to current operations.</div>${f.map(([n,v,u],i)=>`<label class="field"><span>${n}</span><div class="inputrow"><input id="cfg${i}" aria-label="${n}" type="number" min="0" step="any" value="${state.configs[current]?.[i]??v}" ${!canEdit()?'disabled':''}><span style="flex:0;white-space:nowrap;padding:10px">${u}</span></div></label>`).join('')}<button class="primary" onclick="saveConfig()" ${!canEdit()?'disabled':''}>Publish module rules locally</button></div><div><div class="card"><h2>Available shared resources</h2><p class="muted">These can be used in this module’s SOP editor.</p>${resourcesFor(current).map(x=>`<div class="linkline">${x}</div>`).join('')}<button style="margin-top:16px" onclick="go('Common','Sharing')">Manage sharing →</button></div><div class="card"><h2>Connect rules to work</h2><p class="muted">Questions collect answers. Conditions decide the path. Actions tell the operator what to do next.</p><button onclick="go('${current}','SOPs')">Open ${current} SOPs →</button></div></div></div>`}
function formula(){let w=Number($('#weight').value),m=Number($('#margin').value);$('#formula').textContent=`Effective rule: measured weight ${$('#comparison').value} ${(w-m).toFixed(1)} kg (${w} kg minimum − ${m} kg allowance). At exactly ${(w-m).toFixed(1)} kg: ${$('#comparison').value==='>'?'not eligible':'eligible'}.`}
function saveSales(){let v={weight:Number($('#weight').value),margin:Number($('#margin').value),rate:Number($('#rate').value),comparison:$('#comparison').value,version:state.sales.version+1};if(!$('#weight').value||!$('#margin').value||!$('#rate').value||!Number.isFinite(v.weight+v.margin+v.rate)||v.weight<=0||v.margin<0||v.margin>=v.weight||v.rate<=0){toast('Enter a positive weight and rate; allowance must be below the minimum.');return}window.pendingSales=v;modal('Publish Sales business rules',`<p>This updates the local prototype’s published values in Sales and Weighing.</p><div class="card"><div class="linkline">Eligibility <b>${esc(v.comparison)} ${v.weight-v.margin} kg</b></div><div class="linkline">Target rate <b>₹${v.rate} / kg</b></div><div class="linkline">Consumers <b>Sales, Weighing</b></div></div><button class="primary" onclick="state.sales=window.pendingSales;record('Published Sales rules v'+state.sales.version);closeModal();render();toast('Rules published locally. Weighing now uses the updated values.')">Publish locally</button>`)}function saveConfig(){let v=(fields[current]||[]).map((_,i)=>Number($('#cfg'+i).value));if(v.some((x,i)=>!Number.isFinite(x)||x<0||!$('#cfg'+i).value)||(current==='Preventive Care'&&(v[1]>=v[2]||v[0]>100))){toast('Enter valid non-negative values.');return}state.configs[current]=v;record('Published '+current+' rules');toast('Module rules saved locally')}
function resourcesFor(m){return [...(state.shared.photo.includes(m)?['Common · Photo evidence']:[]),...(state.shared.temperature.includes(m)?['Common · Temperature question']:[]),...(state.shared.medicines.includes(m)||m==='Health'?['Health · Medicine catalogue']:[]),...(state.shared.approval.includes(m)?['Common · Request approval']:[])]}
function record(text){state.history.unshift({text,date:new Date().toLocaleString(),module:current});persist()}
function commonView(){if(tab==='Sharing'){$('#content').innerHTML=`<div class="heading"><div><h2>Share once. Reuse where it belongs.</h2><p>Sharing exposes a resource to the SOP builder. It does not grant permission to administer medicine or change inventory.</p></div></div><div class="card"><div class="cardheader"><h2>Resource access by module</h2><span class="badge">Company scope</span></div><div class="tablewrap"><table><thead><tr><th>Resource / owner</th>${modules.map(m=>`<th class="center">${m==='Preventive Care'?'Vaccination':m}</th>`).join('')}</tr></thead><tbody>${[['medicines','Medicine catalogue','Health · Catalogue'],['temperature','Temperature measurement','Common · Question'],['photo','Photo evidence','Common · Question'],['approval','Request approval','Common · Action']].map(([key,title,owner])=>`<tr><td><b>${title}</b><br><span class="muted">${owner}</span></td>${modules.map(m=>`<td class="center"><input type="checkbox" aria-label="Share ${title} with ${m}" ${state.shared[key].includes(m)||(key==='medicines'&&m==='Health')?'checked':''} ${!canEdit()||(key==='medicines'&&m==='Health')?'disabled':''} onchange="share('${key}','${m}',this.checked)"></td>`).join('')}</tr>`).join('')}<tr><td><b>Sale eligibility & target rate</b><br><span class="muted">Sales · Required business dependency</span></td>${modules.map(m=>`<td class="center">${['Sales','Weighing'].includes(m)?'<span class="badge blue">Linked</span>':'—'}</td>`).join('')}</tr></tbody></table></div><div class="hint">Health always retains its own catalogue. Sales → Weighing is a required product dependency, not an optional share.</div></div><div class="two"><div class="card"><h2>Health medicine catalogue</h2><p class="muted">Illustrative entries for the prototype. The owning module manages availability.</p><div class="linkline"><div>Vet-approved treatment A<br><span class="muted">Active · Demonstration entry · No dose prescribed</span></div><span class="badge">Available</span></div><div class="linkline"><div>Vet-approved treatment B<br><span class="muted">Active · Demonstration entry · No dose prescribed</span></div><span class="badge">Available</span></div></div><div class="card"><h2>Try the sharing behaviour</h2><p class="muted">Uncheck Procurement for Medicine catalogue. The procurement action inspector will no longer offer medicine selection, and any existing reference will block publishing.</p><button onclick="go('Procurement','Editor');selected='action';renderEditor()">Open Procurement action →</button></div></div>`;return}let actions=tab==='Action library';$('#content').innerHTML=`<div class="heading"><div><h2>${actions?'Reusable actions':'Reusable questions'}</h2><p>${actions?'Actions are separate from answers; choose them after a decision.':'Reuse the question definition. Each workflow owns what happens after the answer.'}</p></div><button class="primary" onclick="newLibrary(${actions})" ${!canEdit()?'disabled':''}>+ New ${actions?'action':'question'}</button></div><div class="library">${(actions?[{name:'Request approval',type:'Approval',desc:'Ask the designated supervisor to review the outcome.'},{name:'Use configured item',type:'Catalogue action',desc:'Reference an active item from Items Config. Item sharing controls availability.'},...(state.customLibrary||[]).filter(x=>x.action)]:[{name:'Temperature measurement',type:'Number · °F',desc:'Collect a measured value. Thresholds and branches belong to the consuming SOP.'},{name:'Photo evidence',type:'Photo',desc:'Capture visual evidence. Proof requirements belong to the feature.'},...(state.customLibrary||[]).filter(x=>!x.action)]).map((x,i)=>`<div class="card"><div class="cardheader"><h2>${esc(x.name)}</h2><span class="badge ${actions?'purple':'blue'}">${esc(x.type)}</span></div><p>${esc(x.desc)}</p><div class="actions"><span class="muted">${x.draft?'Draft':'Published · v'+state.libraryVersion}</span><div class="spacer"></div><button onclick="libraryDetailByIndex(${actions},${i})">${x.draft?'Review & publish':'View definition'} →</button></div></div>`).join('')}</div>`}
function share(k,m,on){let references=Object.entries(state.sops).filter(([name,s])=>name===m&&s.nodes.some(n=>n.action==='Select medicine'));if(!on&&k==='medicines'&&references.length){modal('Remove catalogue access?',`<p>${esc(m)} has a workflow using this catalogue. Removing access will block its validation and simulation until the action is changed or sharing is restored.</p><button class="danger" onclick="applyShare('${k}','${m}',false);closeModal();render()">Remove access</button>`);return}applyShare(k,m,on)}function applyShare(k,m,on){state.shared[k]=state.shared[k].filter(x=>x!==m);if(on)state.shared[k].push(m);record(`${on?'Shared':'Removed'} ${k} ${on?'with':'from'} ${m}`);toast('Sharing updated locally. SOP resource availability updated.')}
function libraryDetailByIndex(action,index){let names=action?['Request approval','Use configured item']:['Temperature measurement','Photo evidence'];let custom=(state.customLibrary||[]).filter(x=>!!x.action===action);let name=index<2?names[index]:custom[index-2].name;libraryDetail(name,action,index)}function shareDefinition(i,m,on){let d=state.customLibrary[i];d.modules??=[...modules];d.modules=d.modules.filter(x=>x!==m);if(on)d.modules.push(m);record('Updated sharing for '+d.name);toast('Definition availability updated locally')}function publishLibraryIndex(index){publishLibrary(state.customLibrary[index].name)}
function newLibrary(action){modal('New reusable '+(action?'action':'question'),`<label class="field"><span>Name</span><input id="libname" placeholder="e.g. Animal identity check"></label><label class="field"><span>Type</span><select id="libtype">${(action?['Instruction','Request approval']:['Text','Number','Yes / No','Single choice','Multiple choice','Date','Photo','Video','Catalogue']).map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Operator guidance</span><textarea id="libdesc"></textarea></label><button class="primary" onclick="saveLibrary(${action})">Save draft</button>`)}function saveLibrary(action){let name=$('#libname').value.trim();if(!name){toast('Enter a name');return}if(['Temperature measurement','Photo evidence','Request approval','Use configured item',...(state.customLibrary||[]).map(x=>x.name)].some(x=>x.toLowerCase()===name.toLowerCase())){toast('A definition with this name already exists. Choose a unique name.');return}(state.customLibrary??=[]).push({name,type:$('#libtype').value,desc:$('#libdesc').value,action,draft:true,modules:[...modules]});record('Created library draft: '+name);closeModal();render();toast('Reusable definition saved as draft')}
function libraryDetail(name,action,index){let custom=(state.customLibrary||[]).find(x=>x.name===name);modal(name,`<div class="notice">${action?'Reusable action definition':'Reusable question definition'} · Branches are configured separately in each SOP.</div><p>${custom?esc(custom.desc):'The owner maintains this definition. Access is controlled in the sharing matrix.'}</p>${custom?`<span class="label">Available to modules</span>${modules.map(m=>`<label class="checkrow"><input type="checkbox" ${(!custom.modules||custom.modules.includes(m))?'checked':''} ${!canEdit()?'disabled':''} onchange="shareDefinition(${state.customLibrary.indexOf(custom)},'${m}',this.checked)">${m}</label>`).join('')}`:''}${custom?.draft?`<button class="primary" onclick="publishLibraryIndex(${(state.customLibrary||[]).indexOf(custom)})" ${!canEdit()?'disabled':''}>Publish definition locally</button>`:`<button onclick="closeModal();go('Common','Sharing')">Manage module access</button>`}`)}function publishLibrary(name){state.customLibrary.find(x=>x.name===name).draft=false;state.libraryVersion++;record('Published library definition '+name);closeModal();render();toast('Definition published. Available in SOP question type picker.')}
function historyView(){$('#content').innerHTML=`<div class="card"><h2>Local change history</h2><p class="muted">Draft and publication events in this browser.</p>${state.history.filter(x=>current==='Common'||x.module===current).map(x=>`<div class="linkline"><b>${esc(x.text)}</b><span class="muted">${esc(x.date)}</span></div>`).join('')||'<div class="empty">No changes yet. Save a configuration or publish a workflow to begin.</div>'}</div>`}
function sopsView(){if(!canEdit()){let published=[...(sop().published?[{p:sop().published,index:-1}]:[]),...(state.archivedSops?.[current]||[]).map((s,index)=>({p:s.published,index})).filter(x=>x.p)];$('#content').innerHTML=published.length?`<div class="grid">${published.map(({p,index})=>`<div class="card"><h2>${esc(p.title)}</h2><p>Published v${p.version} · Read only</p><button onclick="${index===-1?'startSim()':'switchSop('+index+');startSim()'}">Preview published workflow</button></div>`).join('')}</div>`:'<div class="card"><h2>No published workflow</h2><p>A CEO / CXO must publish the workflow before operators can use it.</p></div>';return}let s=sop();$('#content').innerHTML=`<div class="heading"><div><h2>Operator workflows</h2><p>Build questions, decisions and actions. Test every path before publishing.</p></div><button class="primary" onclick="newSop()" ${!canEdit()?'disabled':''}>+ New SOP</button></div><div class="grid">${(state.archivedSops?.[current]||[]).map((a,i)=>`<div class="card"><h2>${esc(a.title)}</h2><p class="muted">${a.version?'Published v'+a.version:'Draft'}</p><button onclick="switchSop(${i})">Open workflow →</button></div>`).join('')}<div class="card sopcard" onclick="go('${current}','Editor')" tabindex="0" onkeydown="if(event.key==='Enter')go('${current}','Editor')"><div class="cardheader"><h2>${esc(s.title)}</h2><span class="badge">${s.version?'Published v'+s.version:'Draft'}</span></div><p class="muted">${s.nodes.filter(n=>n.type==='question').length} questions · ${s.nodes.filter(n=>n.type==='condition').length} decisions · ${s.nodes.filter(n=>n.type==='action').length} actions</p><div class="flowmini"><b>Question</b>→<b>Decision</b>→<b>Action</b></div><span style="color:var(--brand)">Open workflow →</span></div></div>`}
function switchSop(i){let a=state.archivedSops[current];let old=sop();state.sops[current]=a[i];a[i]=old;persist();go(current,'Editor')}
function newSop(){modal('Create SOP',`<label class="field"><span>Workflow name</span><input id="sopname" placeholder="e.g. Arrival inspection"></label><p class="muted">Your existing workflow stays in the module’s workflow list. Start a separate draft here.</p><button class="primary" onclick="createSop()">Create draft</button>`)}function createSop(){let name=$('#sopname').value.trim();if(!name)return toast('Enter a workflow name');(state.archivedSops??={})[current]??=[];state.archivedSops[current].push(structuredClone(sop()));state.sops[current]=initialSop(current);sop().title=name;persist();closeModal();go(current,'Editor')}
function renderEditor(){if(!canEdit()){let p=sop().published;$('#main').innerHTML=`<div class="eyebrow">${current} · PUBLISHED SOP</div><h1>${p?esc(p.title):'No published SOP'}</h1><p>${p?'Published v'+p.version+' · Read only':'A CEO / CXO must publish a workflow first.'}</p><button onclick="go('${current}','SOPs')">← SOPs</button>${p?'<button onclick="startSim()">Preview published operator flow</button>':''}`;return}let s=sop();if(!s.nodes.some(n=>n.id===selected))selected=s.nodes[0]?.id;$('#main').innerHTML=`<div class="eyebrow">${current} · SOP WORKFLOW</div><div class="heading"><div><h1>${esc(s.title)}</h1><p>Draft workspace <span class="version">· ${s.version?'Published v'+s.version+' available':'Not published yet'}</span></p></div><div class="actions"><button onclick="go('${current}','SOPs')">← SOPs</button><button onclick="saveDraft()" ${!canEdit()?'disabled':''}>Save draft</button><button onclick="startSim()">▷ Test as operator</button><button class="primary" onclick="publishSop()" ${!canEdit()?'disabled':''}>Review & publish</button></div></div><div class="toolbar"><div class="actions"><button onclick="addNode()" ${!canEdit()?'disabled':''}>+ Add step</button><button onclick="validateDialog()">✓ Validate</button><button onclick="workflowVersions()">Versions</button></div><span class="muted">Drag to arrange · Select a step to edit connections</span><div class="actions"><button aria-label="Zoom out" onclick="setZoom(-.1)">−</button><span id="zoomlabel">${Math.round(zoom*100)}%</span><button aria-label="Zoom in" onclick="setZoom(.1)">+</button><button onclick="zoom=1;renderEditor()">Reset view</button></div></div><div class="editor"><div class="canvas"><div class="canvasinner" style="transform:scale(${zoom})" id="graph"></div></div><section class="inspector" id="inspector"></section></div><div class="hint">Local workflow prototype. Published snapshots are versioned here; this does not publish to the live app. ${['Health','Procurement','Preventive Care'].includes(current)?'103°F is the supplied scenario, not a medical recommendation. Treatment entries require a vet-approved protocol.':''}</div>`;drawGraph();inspect()}
function connections(n){return n.type==='condition'?[['Match',n.yes],['Otherwise',n.no]]:n.type==='end'?[]:[['Next',n.next]]}function drawGraph(){let nodes=sop().nodes;let width=Math.max(780,...nodes.map(n=>n.x+260)),height=Math.max(740,...nodes.map(n=>n.y+150));$('#graph').style.width=width+'px';$('#graph').style.height=height+'px';$('#graph').innerHTML=`<svg width="${width}" height="${height}" style="position:absolute;pointer-events:none"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#557c43"/></marker></defs>${nodes.flatMap(n=>connections(n).map(([label,id])=>{let d=nodes.find(x=>x.id===id);if(!d)return '';let x=n.x+110,y=n.y+92,xx=d.x+110,yy=d.y;return `<path class="edge" marker-end="url(#arrow)" d="M${x},${y} C${x},${y+40} ${xx},${yy-40} ${xx},${yy}"/><text class="edge-label" x="${(x+xx)/2+8}" y="${(y+yy)/2}">${n.type==='condition'?label:''}</text>`})).join('')}</svg>${nodes.map(n=>`<div class="node ${n.type} ${n.id===selected?'selected':''}" style="left:${n.x}px;top:${n.y}px" data-node="${n.id}" tabindex="0" role="button" aria-label="Edit ${esc(n.label)}"><div class="ntype">${({start:'↗ Trigger',question:'? Question',condition:'◇ Decision',action:'↳ Action',end:'◎ Finish'})[n.type]}</div><div class="ntext">${esc(n.label)}</div><div class="nmeta">${esc(n.type==='question'?n.answer+(n.unit?' · '+n.unit:''):n.type==='condition'?n.op+' '+n.value:n.type==='action'?n.action:n.type==='start'?'Manual · Operator initiated':'Record result')}</div></div>`).join('')}`;document.querySelectorAll('[data-node]').forEach(el=>{el.onclick=()=>{selected=el.dataset.node;drawGraph();inspect()};el.onkeydown=e=>{if(e.key==='Enter'){selected=el.dataset.node;drawGraph();inspect()}};el.onpointerdown=e=>{if(!canEdit())return;let n=nodes.find(n=>n.id===el.dataset.node),sx=e.clientX,sy=e.clientY,ox=n.x,oy=n.y;el.setPointerCapture(e.pointerId);el.onpointermove=v=>{if(Math.hypot(v.clientX-sx,v.clientY-sy)<4)return;n.x=Math.max(10,ox+(v.clientX-sx)/zoom);n.y=Math.max(10,oy+(v.clientY-sy)/zoom);el.style.left=n.x+'px';el.style.top=n.y+'px'};el.onpointerup=()=>{el.onpointermove=null;selected=n.id;persist();dirty=false;drawGraph();inspect()}}})}
function destination(value,attr){return `<select aria-label="${attr} destination" onchange="editNode('${attr}',this.value)" ${!canEdit()?'disabled':''}><option value="">Choose destination…</option>${sop().nodes.filter(n=>n.id!==selected).map(n=>`<option value="${n.id}" ${n.id===value?'selected':''}>${esc(n.label)}</option>`).join('')}</select>`}function inspect(){let n=sop().nodes.find(x=>x.id===selected);if(!n)return;let dis=!canEdit()?'disabled':'';let types=['Text','Number','Yes / No','Single choice','Multiple choice','Date',...(state.shared.temperature.includes(current)?['Shared: Temperature measurement']:[]),...(state.shared.photo.includes(current)?['Photo']:[]),'Video',...(state.shared.medicines.includes(current)||current==='Health'?['Catalogue']:[]),...(state.customLibrary||[]).filter(x=>!x.draft&&!x.action&&(!x.modules||x.modules.includes(current))).map(x=>'Shared: '+x.name)];$('#inspector').innerHTML=`<div class="cardheader"><h2>Step settings</h2><span class="badge ${n.type==='question'?'blue':'purple'}">${n.type}</span></div>${n.sharedDefinition?`<div class="notice">Shared definition: ${esc(n.sharedDefinition)}<br><span class="muted">This SOP owns its branch rules.</span></div>`:''}<label class="field"><span>Title / operator prompt</span><input aria-label="Step title" value="${esc(n.label)}" oninput="editNode('label',this.value)" ${dis}></label>${n.type==='question'?`<label class="field"><span>Answer type</span><select aria-label="Answer type" onchange="editNode('answer',this.value,true)" ${dis}>${types.map(t=>`<option ${t===n.answer?'selected':''}>${esc(t)}</option>`).join('')}</select></label>${n.answer==='Number'?`<div class="inputrow"><label class="field"><span>Unit</span><select aria-label="Unit" onchange="editNode('unit',this.value)" ${dis}>${['°F','°C','kg','g','ml','₹','%','count'].map(u=>`<option ${u===n.unit?'selected':''}>${u}</option>`).join('')}</select></label><label class="field"><span>Minimum</span><input aria-label="Minimum answer" type="number" value="${n.min??0}" onchange="editNode('min',Number(this.value))" ${dis}></label><label class="field"><span>Maximum</span><input aria-label="Maximum answer" type="number" value="${n.max??100}" onchange="editNode('max',Number(this.value))" ${dis}></label></div>`:''}${['Single choice','Multiple choice'].includes(n.answer)?`<label class="field"><span>Choices (comma separated)</span><input aria-label="Answer choices" value="${esc(n.choices||'Good, Needs attention')}" oninput="editNode('choices',this.value)" ${dis}></label>`:''}<p class="muted">Required question. Answers are collected before continuing.</p>`:''}${n.type==='condition'?`<label class="field"><span>Answer to check</span><select aria-label="Decision source" onchange="editNode('source',this.value)" ${dis}>${sop().nodes.filter(x=>x.type==='question').map(q=>`<option value="${q.id}" ${n.source===q.id?'selected':''}>${esc(q.label)}</option>`).join('')}</select></label><div class="inputrow"><label class="field"><span>Comparison</span><select aria-label="Decision comparison" onchange="editNode('op',this.value)" ${dis}>${['>','>=','<','<=','=','!=','contains'].map(o=>`<option ${o===n.op?'selected':''}>${esc(o)}</option>`).join('')}</select></label><label class="field"><span>Value</span><input aria-label="Decision value" value="${esc(n.value)}" oninput="editNode('value',this.value)" ${dis}></label></div><label class="field"><span>If condition matches</span>${destination(n.yes,'yes')}</label><label class="field"><span>Otherwise (required fallback)</span>${destination(n.no,'no')}</label>`:''}${n.type==='action'?`<label class="field"><span>Action</span><select aria-label="Action type" onchange="editNode('action',this.value,true)" ${dis}>${n.action==='Select medicine'&&current!=='Health'&&!state.shared.medicines.includes(current)?'<option selected disabled>Select medicine · access removed</option>':''}${['Instruction',...(state.shared.approval.includes(current)?['Request approval']:[]),'Create follow-up',...(state.customLibrary||[]).filter(x=>!x.draft&&x.action&&(!x.modules||x.modules.includes(current))).map(x=>x.name),...(state.shared.medicines.includes(current)||current==='Health'?['Select medicine']:[])].map(a=>`<option ${n.action===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label>${n.action==='Select medicine'?`<label class="field"><span>Health · Medicine catalogue</span>${state.shared.medicines.includes(current)||current==='Health'?`<select aria-label="Medicine" onchange="editNode('medicine',this.value)" ${dis}><option value="">Select approved entry…</option>${['Vet-approved treatment A','Vet-approved treatment B'].map(a=>`<option ${n.medicine===a?'selected':''}>${a}</option>`).join('')}</select>`:'<p class="error">Catalogue access removed. Restore sharing or choose another action.</p>'}</label><div class="notice">Selection references a vet-approved protocol. It does not authorize treatment or prescribe a dose.</div>`:''}<label class="field"><span>Operator instruction</span><textarea aria-label="Action instruction" oninput="editNode('instruction',this.value)" ${dis}>${esc(n.instruction||'Follow your approved protocol and record the outcome.')}</textarea></label>`:''}${!['condition','end'].includes(n.type)?`<label class="field"><span>Continue to</span>${destination(n.next,'next')}</label>`:''}<div class="actions">${!['start','end'].includes(n.type)?`<button class="danger" onclick="deleteNode()" ${dis}>Delete step</button>`:''}<button onclick="startSim()">Test flow</button></div><div class="hint">Draft edits are saved locally automatically. Publishing creates a separate operator version.</div>`}
function editNode(k,v,refresh=false){if(!canEdit())return;let n=sop().nodes.find(x=>x.id===selected);if(k==='answer'&&v.startsWith('Shared: ')){let d=v==='Shared: Temperature measurement'?{type:'Number',builtin:true}:(state.customLibrary||[]).find(x=>x.name===v.slice(8));n.sharedDefinition=v.slice(8);n.answer=d.type;n.min=d.builtin?90:0;n.max=d.builtin?115:100;if(d.builtin)n.unit='°F';n.choices='Good, Needs attention';refresh=true}else {n[k]=v;if(k==='answer'){delete n.sharedDefinition;if(v==='Number'){n.min??=0;n.max??=100;n.unit??='kg'}}}persist();dirty=false;drawGraph();if(refresh)inspect()}function setZoom(n){zoom=Math.max(.5,Math.min(1.4,zoom+n));renderEditor()}function addNode(){modal('Add a workflow step',`<label class="field"><span>Step type</span><select id="newtype"><option value="question">Question · collect an answer</option><option value="condition">Decision · branch on an answer</option><option value="action">Action · tell the operator what to do</option></select></label><label class="field"><span>Title</span><input id="newlabel" placeholder="What should happen here?"></label><button class="primary" onclick="createNode()">Add step</button>`)}function createNode(){let label=$('#newlabel').value.trim();if(!label)return toast('Enter a step title');let type=$('#newtype').value,id='n'+Date.now();sop().nodes.push({id,type,label,answer:'Text',action:'Instruction',source:'q1',op:'=',value:'Yes',next:'',yes:'',no:'',x:480,y:160+sop().nodes.length*30});selected=id;persist();dirty=false;closeModal();renderEditor();toast('Step added. Connect it using destination selectors.')}function deleteNode(){let n=sop().nodes.find(x=>x.id===selected);sop().nodes=sop().nodes.filter(x=>x.id!==selected);persist();dirty=false;selected='start';renderEditor();toast('Step removed. Validate to repair any missing connections.')}function saveDraft(){if(!canEdit())return;record('Saved '+sop().title+' draft');dirty=false;toast('Draft saved in this browser')}
function validateWorkflow(s,m=current){let errors=[],nodes=s.nodes,map=new Map(nodes.map(n=>[n.id,n])),start=nodes.find(n=>n.type==='start');if(!start)errors.push('A start step is required.');if(!nodes.some(n=>n.type==='end'))errors.push('A finish step is required.');nodes.forEach(n=>{if(!n.label.trim())errors.push('Every step needs a title.');connections(n).forEach(([label,id])=>{if(!id||!map.has(id))errors.push(n.label+': '+label+' destination is missing.');});if(n.type==='condition'){let q=map.get(n.source);if(q?.answer==='Number'&&(!String(n.value).trim()||!Number.isFinite(Number(n.value))))errors.push(n.label+': numeric questions require a numeric comparison value.');if(!q||q.type!=='question')errors.push(n.label+': choose a question to evaluate.');if(!String(n.value).trim()||(['>','>=','<','<='].includes(n.op)&&!Number.isFinite(Number(n.value))))errors.push(n.label+': enter a valid comparison value.')}if(n.type==='question'&&n.answer==='Number'&&(!Number.isFinite(n.min)||!Number.isFinite(n.max)||n.min>=n.max))errors.push(n.label+': minimum must be below maximum.');if(n.sharedDefinition){let d=n.sharedDefinition==='Temperature measurement'?{modules:state.shared.temperature}:(state.customLibrary||[]).find(x=>x.name===n.sharedDefinition);if(!d||d.draft||(d.modules&&!d.modules.includes(m)))errors.push(n.label+': shared definition is unavailable.')}if(n.type==='action'){let d=(state.customLibrary||[]).find(x=>x.action&&x.name===n.action);if(d&&(d.draft||(d.modules&&!d.modules.includes(m))))errors.push(n.label+': shared action is unavailable.')}if(n.type==='question'&&n.answer==='Catalogue'&&m!=='Health'&&!state.shared.medicines.includes(m))errors.push(n.label+': Health catalogue access is not shared.');if(n.type==='question'&&n.answer==='Photo'&&!state.shared.photo.includes(m))errors.push(n.label+': Photo evidence is not shared with this module.');if(n.type==='action'&&n.action==='Request approval'&&!state.shared.approval.includes(m))errors.push(n.label+': Request approval is not shared with this module.');if(n.type==='action'&&n.action==='Select medicine'){if(m!=='Health'&&!state.shared.medicines.includes(m))errors.push(n.label+': Health catalogue access is not shared.');if(!n.medicine)errors.push(n.label+': select a medicine catalogue entry.')}});let visited=new Set(),active=new Set(),seenPaths=new Set();function visit(id,pathAnswers=new Set()){if(active.has(id)){errors.push('Cycle detected. Every path must reach completion.');return}let signature=id+'|'+[...pathAnswers].sort().join(',');if(seenPaths.has(signature))return;seenPaths.add(signature);let n=map.get(id);if(!n)return;visited.add(id);active.add(id);if(n.type==='question')pathAnswers=new Set([...pathAnswers,n.id]);if(n.type==='condition'&&!pathAnswers.has(n.source))errors.push(n.label+': source answer must be collected before this decision.');connections(n).forEach(([,id])=>visit(id,new Set(pathAnswers)));active.delete(id)}if(start)visit(start.id);nodes.filter(n=>!visited.has(n.id)).forEach(n=>errors.push(n.label+': step is not reachable from start.'));return [...new Set(errors)]}
function validateDialog(){let errors=validateWorkflow(sop());modal(errors.length?'Workflow needs attention':'Workflow is valid',errors.length?`<p>Resolve these issues before publishing or simulation.</p>${errors.map(e=>`<div class="notice error">${esc(e)}</div>`).join('')}`:`<div class="notice">All paths are connected, decisions have a fallback, and required resources are available.</div><button class="primary" onclick="closeModal();startSim()">Test as operator</button>`)}function publishSop(){let errors=validateWorkflow(sop());if(errors.length)return validateDialog();modal('Publish workflow locally',`<p>${esc(sop().title)} · New version ${sop().version+1}</p><div class="notice">New operator runs use this snapshot. Existing runs retain their original version. This prototype only simulates that behaviour in this browser.</div><div class="linkline">Questions <b>${sop().nodes.filter(n=>n.type==='question').length}</b></div><div class="linkline">Module <b>${current}</b></div><button class="primary" style="margin-top:20px" onclick="confirmPublish()">Publish local version</button>`)}function confirmPublish(){let s=sop();if(s.published)(s.versions??=[]).push(structuredClone(s.published));s.version++;s.published=structuredClone({nodes:s.nodes,title:s.title,version:s.version});record('Published '+s.title+' v'+s.version);dirty=false;closeModal();renderEditor();toast('Workflow published locally')}
function compare(a,op,b){if(op==='contains')return Array.isArray(a)?a.includes(b):String(a).includes(b);if(['>','>=','<','<='].includes(op)){a=Number(a);b=Number(b);if(!Number.isFinite(a)||!Number.isFinite(b))return false;return op==='>'?a>b:op==='>='?a>=b:op==='<'?a<b:a<=b}if(typeof a==='number'&&String(b).trim()&&Number.isFinite(Number(b)))return op==='='?a===Number(b):a!==Number(b);return op==='='?String(a)===String(b):String(a)!==String(b)}
function startSim(){let s=sop(),snapshot=canEdit()?s:(s.published||null);if(!snapshot){toast('No published workflow available for this role.');return}let errors=validateWorkflow(snapshot);if(errors.length){if(canEdit())validateDialog();else toast('Published workflow cannot run: '+errors[0]);return}sim={nodes:structuredClone(snapshot.nodes),id:snapshot.nodes.find(n=>n.type==='start').next,answers:{},path:[],title:snapshot.title};renderSim()}
function renderSim(){let n=sim.nodes.find(n=>n.id===sim.id);if(!n)return;if(n.type==='condition'){let a=sim.answers[n.source],match=compare(a,n.op,n.value);sim.path.push(`${n.label}: ${a} ${n.op} ${n.value} → ${match?'Match':'Otherwise'}`);sim.id=match?n.yes:n.no;renderSim();return}let body=n.type==='end'?`<span class="badge">Complete</span><h2 style="margin-top:20px">${esc(n.label)}</h2><p>Outcome recorded in this test only.</p>`:n.type==='action'?`<span class="badge purple">Action</span><h2 style="margin:20px 0">${esc(n.label)}</h2><p>${esc(n.instruction||'Follow your approved protocol and record the outcome.')}</p>${n.action==='Select medicine'?`<div class="notice">Selected: ${esc(n.medicine)}<br>Use the approved veterinary protocol.</div>`:`<div class="notice">${esc(n.action)} · Simulated; nothing is sent.</div>`}<button class="primary" style="width:100%" onclick="simAdvance()">Acknowledge & continue</button>`:`<span class="badge blue">Required question</span><h2 style="margin:20px 0">${esc(n.label)}</h2>${simInput(n)}<div id="simerror" class="error hint"></div><button class="primary" style="width:100%;margin-top:18px" onclick="simAnswer()">Continue →</button>`;$('#overlay').innerHTML=`<div class="modalbg"><section class="modal wide"><div class="modalhead"><div><h2>Operator preview</h2><span class="muted">${canEdit()?'Current draft':'Published version'} · ${esc(sim.title)} · No live actions</span></div><button onclick="closeModal()" aria-label="Close operator preview">✕</button></div><div class="two simlayout"><div class="phone"><span class="muted">Mesha · ${current}</span><div class="progress"><span style="width:${n.type==='end'?100:Math.min(90,(sim.path.length+1)*20)}%"></span></div>${body}</div><div><h3>Path taken</h3><div class="timeline">${sim.path.map(p=>`<div class="muted">${esc(p)}</div>`).join('')||'<div class="muted">Answer the question to see the selected branch.</div>'}</div><button onclick="startSim()">↻ Restart test</button></div></div></section></div>`}
function simInput(n){if(n.answer==='Yes / No')return '<select id="simvalue" aria-label="Operator answer"><option value="">Select answer…</option><option>Yes</option><option>No</option></select>';if(n.answer==='Single choice'||n.answer==='Catalogue')return `<select id="simvalue" aria-label="Operator answer"><option value="">Select answer…</option>${(n.answer==='Catalogue'?['Vet-approved treatment A','Vet-approved treatment B']:(n.choices||'Good, Needs attention').split(',')).map(c=>`<option>${esc(c.trim())}</option>`).join('')}</select>`;if(n.answer==='Multiple choice')return (n.choices||'Good, Needs attention').split(',').map(c=>`<label class="checkrow"><input class="simcheck" type="checkbox" value="${esc(c.trim())}">${esc(c.trim())}</label>`).join('');return `<input id="simvalue" aria-label="Operator answer" type="${n.answer==='Number'?'number':n.answer==='Date'?'date':['Photo','Video'].includes(n.answer)?'file':'text'}" ${['Photo','Video'].includes(n.answer)?`accept="${n.answer==='Photo'?'image':'video'}/*"`:''} ${n.answer==='Number'?`min="${n.min}" max="${n.max}" step="any"`:''}><div class="hint">${n.answer==='Number'?`${n.min}–${n.max} ${esc(n.unit)} · Required`:['Photo','Video'].includes(n.answer)?'File name is used for this test. No upload occurs.':''}</div>`}
function simAnswer(){let n=sim.nodes.find(n=>n.id===sim.id),el=$('#simvalue'),v=n.answer==='Multiple choice'?[...document.querySelectorAll('.simcheck:checked')].map(x=>x.value):el?.value;if(!v||!v.length){$('#simerror').textContent='Answer this question before continuing.';return}if(n.answer==='Number'){v=Number(v);if(!Number.isFinite(v)||v<n.min||v>n.max){$('#simerror').textContent=`Enter a number from ${n.min} to ${n.max}.`;return}}sim.answers[n.id]=v;sim.path.push(n.label+': '+(Array.isArray(v)?v.join(', '):v));sim.id=n.next;renderSim()}function simAdvance(){let n=sim.nodes.find(n=>n.id===sim.id);sim.path.push('Action acknowledged: '+n.label);sim.id=n.next;renderSim()}
$('#role').onchange=()=>{closeModal();render()};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});render();

function workflowVersions(){let s=sop(),v=[...(s.published?[s.published]:[]),...(s.versions||[]).slice().reverse()];modal('Published workflow versions',v.length?v.map(x=>`<div class="linkline"><div><b>${esc(x.title)}</b><br><span class="muted">${x.nodes.length} steps · Immutable local snapshot</span></div><span class="badge">v${x.version}</span></div>`).join(''):'<p>No versions published yet. Validate and publish the draft first.</p>')}
